1	#!/usr/bin/env node
2	// decider.js — the ONE shared fleet-wide "needs direction" decision daemon
3	// (research/IDLE_TRIGGER_SPEC.md §1.6/§3b, Direction Episodes Phase 3).
4	//
5	// Never a payload: no LLM code runs inside any bot process — this is a standalone daemon,
6	// same pattern as graybridge.js. Start: setsid nohup node decider.js >> logs/decider.log 2>&1 &
7	// Stop: kill the pid in pids/decider.pid (or just SIGTERM/SIGINT it — the pidfile is cleaned
8	// up on exit either way).
9	//
10	// Flow per POLL_MS cycle, for every bot discovered via pids/*.port (+ pids/*.meta for owner
11	// and, since #95's soak-hygiene fix, DECIDER_EXCLUDE=1 spawn-time exclusion -- a throwaway
12	// verification bot spawned alongside a formal soak/race is structurally invisible to this
13	// daemon's polling/budget/LLM path, never just a naming-convention hint):
14	//   1. GET /state; skip unless agenda.direction.state === 'needs_direction' (see agenda.js v22
15	//      / runner.js's own /state.agenda.direction — Phase 1 of this same spec).
16	//   2. Driver grace, CONDITIONAL not flat: an OWNED bot (meta names a driver) gets
17	//      DRIVER_GRACE_MS before the decider answers for it — the driver wins the race by
18	//      default. An unowned bot is answered immediately; no free grace for the driverless fleet.
19	//   3. Dedup (bot,eid) against decider-state.json — one decision per episode, mechanically,
20	//      and it survives a decider restart (the engine's own latches do not survive reinjection,
21	//      this must).
22	//   4. rules.json FIRST (key = why|role|lastError|barrenBucket) — a hit dispatches at zero
23	//      tokens, the codicil's whole point.
24	//   5. On a miss: rate gates (per-bot >=120s, fleet 30/hr, both persisted) -> compact context
25	//      from /state (+ the live skill registry, fetched via /eval) -> ONE Andy-via-Ollama call
26	//      -> map Andy's native !command(args) dialect onto the REAL registry (deterministic,
27	//      closed vocabulary -- see mapAndyCommand) -> dispatch. Felix's ruling (2026-09-02)
28	//      supersedes the original Anthropic-API-key plan: Andy (sweaterdog/andy-4:micro-q8_0,
29	//      served CPU-pinned via local Ollama as andy-cpu:latest) is zero-marginal-cost and was
30	//      always the intended long-term backend (memory: minecraft-llm-backend-plan). Andy is
31	//      fine-tuned on mindcraft-ce's own command dialect and ignores a bare-JSON format
32	//      constraint (smoke test: asked for JSON, replied `!searchForBlock("oak_log", 32)`), so
33	//      the prompt offers that dialect back rather than fighting the model's own distribution --
34	//      registry validation + retry-once-then-skip stays the backstop, same as the Haiku design.
35	//   6. Dispatch: POST /eval __agenda.dirDispatch(eid, {...decision, by:'decider'}) — the eid
36	//      compare-and-set (agenda.js §1.1j) makes a driver's own answer win the race for free; a
37	//      decider dispatch against a stale/already-answered eid is a harmless no-op.
38	//   7. Append decisions.jsonl — the rule-of-twice input for graduating (why,role,...) keys
39	//      into rules.json, and ultimately into ROLE_WORK defaults.
40	//
41	// Vocabulary is CLOSED: dirDispatch/setProject specs only. This can never become a second
42	// deliberative loop driving the body (the idleguard-subsumption law, agenda.js's own header).
43	// Decider down -> graceful degradation: the IDLE role-work floor keeps bots productive exactly
44	// as today; unanswered episodes just accumulate as the open-unclosed alarm (metrics.mjs),
45	// not as silence.
46	'use strict';
47	const fs = require('fs');
48	const path = require('path');
49	const http = require('http');
50	
51	const SELF_DIR = __dirname;
52	const PIDS_DIR = path.join(SELF_DIR, 'pids');
53	const LOGS_DIR = path.join(SELF_DIR, 'logs');
54	const DECISIONS_FILE = path.join(LOGS_DIR, 'decisions.jsonl');
55	const STATE_FILE = path.join(SELF_DIR, 'decider-state.json');
56	const RULES_FILE = path.join(SELF_DIR, 'rules.json');
57	const PID_FILE = path.join(PIDS_DIR, 'decider.pid');
58	
59	const POLL_MS = 20000;
60	const DRIVER_GRACE_MS = 60000;
61	const PER_BOT_MIN_GAP_MS = 120000;
62	const FLEET_CAP_PER_HOUR = 30;             // CPU contention is the new budget, not dollars -- cap stays (Felix's ruling)
63	// #95 soak-hygiene round 2 (2026-09-02, argued in FEEDBACK.md before building): the shared
64	// fleet cap above means a CONCURRENT bot's own LLM calls (a live race, say) compete with a
65	// formal soak's bot for the same 30/hr budget -- if the race consumes it, the soak bot's own
66	// calls can get skipped_cap'd, directly inflating its measured direction-latency for a reason
67	// that has nothing to do with the engine under test. DECIDER_EXCLUDE (spawn.sh's 4th meta
68	// field, see discoverBots() below) solves the DIFFERENT problem of a throwaway bot that
69	// shouldn't be fleet work at all -- a real fleet bot like a race entry is supposed to have
70	// decider support, excluding it would just move the contamination the other direction.
71	// SOAK_BOT names the ONE bot under formal measurement for this decider PROCESS's lifetime
72	// (set at launch, not a standing config) -- its own calls never count against the shared cap
73	// and the shared cap never blocks it, fully symmetric; everyone else keeps sharing the
74	// ordinary cap exactly as before. Still bound by PER_BOT_MIN_GAP_MS -- this is cap isolation,
75	// not a runaway-LLM exemption.
76	const SOAK_BOT = process.env.SOAK_BOT || null;
77	const HANDLED_TTL_MS = 86400000;          // prune decider-state.json's dedup map after 24h
78	const LLM_MISS_RETRY_LIMIT = 2;           // retry-once-then-skip: 2 unusable Andy replies gives up on that episode
79	const OLLAMA_HOST = process.env.OLLAMA_HOST || '127.0.0.1';
80	const OLLAMA_PORT = parseInt(process.env.OLLAMA_PORT || '11434', 10);
81	const ANDY_MODEL = process.env.ANDY_MODEL || 'andy-cpu:latest';   // andy8-cpu:latest is the bigger sibling if micro proves too dumb
82	
83	const log = (m) => console.log(`[${new Date().toISOString()}] ${m}`);
84	
85	// ---- persisted state: survives BOTH a decider restart and a bot's payload reinjection
86	// (agenda.js's own engine-side latches do not survive the latter — see spec §2.3/§2.4) ----
87	function loadState() {
88	  try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')); }
89	  catch (e) { return { handled: {}, lastCallAt: {}, fleetCalls: [] }; }
90	}
91	function pruneHandled(st) {
92	  const cutoff = Date.now() - HANDLED_TTL_MS;
93	  const h = st.handled || {};
94	  for (const k of Object.keys(h)) if (h[k] < cutoff) delete h[k];
95	}
96	function saveState(st) {
97	  pruneHandled(st);
98	  try { fs.mkdirSync(SELF_DIR, { recursive: true }); } catch (e) {}
99	  try { fs.writeFileSync(STATE_FILE, JSON.stringify(st)); } catch (e) { log('state save failed: ' + e.message); }
100	}
101	let state = loadState();
102	
103	function loadRules() {
104	  try { return JSON.parse(fs.readFileSync(RULES_FILE, 'utf8')); }
105	  catch (e) { return {}; }
106	}
107	
108	// ---- bot discovery: pids/*.port (control port, written by spawn.sh) + pids/*.meta
109	// (owner|server|purpose|decider_exclude, the fleet-awareness convention) ----
110	function discoverBots() {
111	  let files;
112	  try { files = fs.readdirSync(PIDS_DIR); } catch (e) { return []; }
113	  const bots = [];
114	  for (const f of files) {
115	    const m = /^(.+)\.port$/.exec(f);
116	    if (!m) continue;
117	    const name = m[1];
118	    let port;
119	    try { port = parseInt(fs.readFileSync(path.join(PIDS_DIR, f), 'utf8').trim(), 10); } catch (e) { continue; }
120	    if (!port) continue;
121	    let owner = null;
122	    // #95 soak-hygiene fix (2026-09-02): a throwaway/verification bot spawned alongside a
123	    // formal soak or race used to draw from the SAME shared fleet-wide LLM budget/rate gates
124	    // as the bot actually being measured, silently -- soak #2 was contaminated exactly this
125	    // way (SchlonzSchorsch, spawned mid-window for an unrelated fix's regression check).
126	    // DECIDER_EXCLUDE=1 at spawn time (spawn.sh's 4th meta field) makes a bot structurally
127	    // invisible to this daemon -- not a "(throwaway)" note in freeform PURPOSE text, which
128	    // existed before and enforced nothing. Excluded bots still run their own engine-side
129	    // agenda ladder exactly as always; only decider.js's polling/budget/LLM path skips them.
130	    let excluded = false;
131	    try {
132	      const meta = fs.readFileSync(path.join(PIDS_DIR, name + '.meta'), 'utf8').trim();
133	      const fields = meta.split('|');
134	      // spawn.sh writes the literal string "unowned" (not an empty field) when no OWNER is
135	      // given -- treat that sentinel as no owner, or every driverless bot would wait out the
136	      // 60s driver grace this daemon's own header comment promises it never gets.
137	      const rawOwner = (fields[0] || '').trim();
138	      owner = (rawOwner && rawOwner !== 'unowned') ? rawOwner : null;
139	      excluded = Boolean((fields[3] || '').trim());
140	    } catch (e) {}
141	    if (excluded) continue;
142	    bots.push({ name, port, owner });
143	  }
144	  return bots;
145	}
