147	// ---- tiny local HTTP helpers (no dependency — matches this codebase's own hand-rolled
148	// style, e.g. graybridge.js's hand-rolled RCON protocol) ----
149	function httpGetJson(port, route, timeoutMs = 5000) {
150	  return new Promise((resolve, reject) => {
151	    const req = http.get({ host: '127.0.0.1', port, path: '/' + route, timeout: timeoutMs }, (res) => {
152	      let data = '';
153	      res.on('data', (c) => { data += c; });
154	      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
155	    });
156	    req.on('error', reject);
157	    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
158	  });
159	}
160	function httpPostJson(port, route, body, timeoutMs = 15000) {
161	  return new Promise((resolve, reject) => {
162	    const payload = Buffer.from(JSON.stringify(body));
163	    const req = http.request({
164	      host: '127.0.0.1', port, path: '/' + route, method: 'POST',
165	      headers: { 'Content-Type': 'application/json', 'Content-Length': payload.length },
166	      timeout: timeoutMs,
167	    }, (res) => {
168	      let data = '';
169	      res.on('data', (c) => { data += c; });
170	      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
171	    });
172	    req.on('error', reject);
173	    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
174	    req.write(payload); req.end();
175	  });
176	}
177	const evalOn = (port, code) => httpPostJson(port, 'eval', { code });
178	
179	// ---- rule key + matching (spec §3b step 4) ----
180	function barrenBucket(n) { n = n || 0; return n === 0 ? '0' : n < 3 ? '1-2' : n < 10 ? '3-9' : '10+'; }
181	function ruleKey(direction, role) {
182	  const detail = (direction && direction.detail) || {};
183	  return [direction && direction.why, role || 'none', detail.lastError || 'none', barrenBucket(detail.barren)].join('|');
184	}
185	
186	// ---- fleet-wide rate cap: persisted rolling 1h window, never engine-side-only (spec §2.3.3) ----
187	function fleetCapOk() {
188	  const cutoff = Date.now() - 3600000;
189	  state.fleetCalls = (state.fleetCalls || []).filter((t) => t > cutoff);
190	  return state.fleetCalls.length < FLEET_CAP_PER_HOUR;
191	}
192	function recordFleetCall() { state.fleetCalls = state.fleetCalls || []; state.fleetCalls.push(Date.now()); }
193	
194	// ---- context ----
195	async function buildContext(b, st) {
196	  let skills = [];
197	  try {
198	    const r = await evalOn(b.port, 'return Object.keys(globalThis.__skills.registry);');
199	    skills = (r && r.result) || [];
200	  } catch (e) { log(`${b.name}: could not fetch skill registry: ${e.message}`); }
201	  return { state: st, skills };
202	}
203	
204	// ---- Andy's native dialect -> our skill registry ----
205	// Standalone copies of the engine's own vocabulary (decider.js is never a payload, no
206	// cross-process import -- same discipline farmskills.js documents for its own copies).
207	const SPECIES_LIST = ['oak', 'spruce', 'birch', 'jungle', 'acacia', 'dark_oak', 'cherry', 'pale_oak', 'mangrove'];
208	const ORE_ALIASES_LIST = {
209	  iron_ore: ['iron_ore', 'deepslate_iron_ore'], gold_ore: ['gold_ore', 'deepslate_gold_ore'],
210	  copper_ore: ['copper_ore', 'deepslate_copper_ore'], coal_ore: ['coal_ore', 'deepslate_coal_ore'],
211	  diamond_ore: ['diamond_ore', 'deepslate_diamond_ore'], emerald_ore: ['emerald_ore', 'deepslate_emerald_ore'],
212	  lapis_ore: ['lapis_ore', 'deepslate_lapis_ore'], redstone_ore: ['redstone_ore', 'deepslate_redstone_ore'],
213	};
214	const UBIQUITOUS_LIST = ['stone', 'deepslate', 'dirt', 'netherrack', 'cobblestone', 'grass_block', 'sand', 'gravel'];
215	const PRODUCE_RESOURCES = new Set(['torch', 'cobblestone', 'coal', 'stick', 'crafting_table']);
216	
217	function normalizeBlockArg(raw) { return String(raw || '').trim().replace(/^["']|["']$/g, '').toLowerCase(); }
218	function stripLogSuffix(name) { return name.replace(/_log$/, '').replace(/_wood$/, ''); }
219	
220	// Curated, deterministic, closed. Andy-4-micro is fine-tuned on mindcraft-ce's !command(args)
221	// syntax; the prompt below offers it a SMALL menu drawn from that same syntax (not its full
222	// ~30-command vocabulary) so it answers inside its own training distribution, and this maps
223	// that answer back onto our real skill params. Anything it says outside this menu, or whose
224	// args don't resolve to something recognizable, is a MISS -- returned as null, never guessed.
225	function mapAndyCommand(cmd, argStrs) {
226	  const num = (s, dflt) => { const n = parseInt(String(s || '').trim(), 10); return Number.isFinite(n) ? n : dflt; };
227	  if (cmd === 'goToSurface') return { skill: 'ascendToSurface', args: {} };
228	  if (cmd === 'searchForBlock' || cmd === 'collectBlocks') {
229	    const block = normalizeBlockArg(argStrs[0]);
230	    const n2 = num(argStrs[1], null);
231	    const species = stripLogSuffix(block);
232	    if (SPECIES_LIST.includes(species)) {
233	      const args = { types: [species] };
234	      if (cmd === 'searchForBlock') args.maxDist = n2 || 32; else args.count = n2 || 4;
235	      return { skill: 'chopTrees', args };
236	    }
237	    const oreKey = Object.keys(ORE_ALIASES_LIST).find((k) => ORE_ALIASES_LIST[k].includes(block)) || null;
238	    if (oreKey || UBIQUITOUS_LIST.includes(block)) {
239	      const args = { target: oreKey || block };
240	      if (cmd === 'searchForBlock') args.maxDist = n2 || 32; else args.count = n2 || 4;
241	      return { skill: 'mineLane', args };
242	    }
243	    return null;
244	  }
245	  if (cmd === 'craftRecipe') {
246	    const item = normalizeBlockArg(argStrs[0]);
247	    const n2 = num(argStrs[1], 16);
248	    if (PRODUCE_RESOURCES.has(item) || /_planks$/.test(item)) return { skill: 'produce', args: { resource: item, count: n2 } };
249	    return null;
250	  }
251	  if (cmd === 'attack') {
252	    const species = normalizeBlockArg(argStrs[0]);
253	    if (species && species !== 'player') return { skill: 'huntAnimals', args: { species: [species] } };
254	    return null;
255	  }
256	  return null;
257	}
258	function parseAndyResponse(raw) {
259	  if (!raw) return null;
260	  const m = /!([A-Za-z_][A-Za-z0-9_]*)\(([^)]*)\)/.exec(raw);
261	  if (!m) return null;
262	  return { cmd: m[1], argStrs: m[2].trim() ? m[2].split(',').map((x) => x.trim()) : [] };
263	}
264	const SITUATIONS = {
265	  unproductive_idle: 'has been idle with no clear task for a while',
266	  project_stalled: 'has a project that stopped making progress',
267	  no_path: 'is stuck -- no path found to its goal',
268	  no_tool: 'lacks a tool it needs',
269	  respawned: 'just died and respawned, and has no project',   // #103
270	};
271	// A bare closed-menu instruction ("reply with exactly one of these five") did NOT reliably hold
272	// Andy-4-micro to the menu in smoke testing -- it answers from its own ~30-command fine-tuned
273	// vocabulary regardless (e.g. `!moveAway(10)`, `!goToPlayer(...)`, `!newAction(...)`, or plain
274	// chat with no `!command` at all). A one-shot example in its OWN dialect measurably improved
275	// compliance on the matching case. This is expected to stay imperfect -- misses are logged with
276	// raw text (not guessed into a dispatch) precisely so the mapping in mapAndyCommand can widen
277	// over time from what Andy actually says, per Felix's "study the dialect" instruction.
278	function buildAndyPrompt(ctx) {
279	  const s = ctx.state;
280	  const a = s.agenda || {};
281	  const d = a.direction || {};
282	  return [
283	    `You are ${s.name}, a Minecraft bot deciding your next action.`,
284	    `Stats: health: ${s.health}, hunger: ${s.food}`,
285	    'Available commands:',
286	    '!goToSurface() - dig upward to open sky',
287	    '!searchForBlock(block_name, distance) - go mine the nearest block of this type',
288	    '!collectBlocks(block_name, count) - mine several blocks of this type nearby',
289	    '!craftRecipe(item_name, count) - craft this item',
290	    '!attack(animal_name) - hunt this animal',
291	    '',
292	    'Example:',
293	    'Situation: has been idle with no clear task for a while',
294	    'Response: !searchForBlock("oak_log", 32)',
295	    '',
296	    `Situation: ${SITUATIONS[d.why] || d.why || 'needs a new task'}`,
297	    'Response:',
298	  ].join('\n');
299	}
300	
301	// Guard inherited from mindcraft-ce/andy-start.sh: refuse the LLM path if Ollama has offloaded
302	// ANDY_MODEL onto the GPU (andy-cpu must stay CPU-pinned). Not loaded yet is NOT a failure --
303	// there's nothing to check until the first call loads it; a request/parse hiccup fails open
304	// (`ok:true`) rather than blocking the whole soak on an ops-check the real /api/chat call would
305	// surface anyway.
306	function checkCpuPinned() {
307	  return new Promise((resolve) => {
308	    const req = http.get({ host: OLLAMA_HOST, port: OLLAMA_PORT, path: '/api/ps', timeout: 5000 }, (res) => {
309	      let data = '';
310	      res.on('data', (c) => { data += c; });
311	      res.on('end', () => {
312	        try {
313	          const j = JSON.parse(data);
314	          const m = (j.models || []).find((mm) => mm.name === ANDY_MODEL || mm.model === ANDY_MODEL);
315	          if (!m) return resolve({ ok: true, loaded: false });
316	          resolve({ ok: (m.size_vram || 0) === 0, loaded: true, vram: m.size_vram || 0 });
317	        } catch (e) { resolve({ ok: true, loaded: false }); }
318	      });
319	    });
320	    req.on('error', () => resolve({ ok: true, loaded: false }));
321	    req.on('timeout', () => { req.destroy(); resolve({ ok: true, loaded: false }); });
322	  });
323	}
324	async function askAndy(ctx) {
325	  const guard = await checkCpuPinned();
326	  if (!guard.ok) {
327	    log(`ABORT LLM path: ${ANDY_MODEL} size_vram=${guard.vram} (>0, on GPU) -- fix the model pin before spending another call`);
328	    return { decision: null, raw: null, aborted: 'gpu_pinned' };
329	  }
330	  const prompt = buildAndyPrompt(ctx);
331	  const body = JSON.stringify({ model: ANDY_MODEL, messages: [{ role: 'user', content: prompt }], stream: false });
332	  const raw = await new Promise((resolve) => {
333	    const req = http.request({
334	      host: OLLAMA_HOST, port: OLLAMA_PORT, path: '/api/chat', method: 'POST',
335	      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
336	      timeout: 30000,
337	    }, (res) => {
338	      let data = '';
339	      res.on('data', (c) => { data += c; });
340	      res.on('end', () => {
341	        try { const j = JSON.parse(data); resolve((j.message && j.message.content) || null); }
342	        catch (e) { log('andy response parse failed: ' + e.message); resolve(null); }
343	      });
344	    });
345	    req.on('error', (e) => { log('andy call failed: ' + e.message); resolve(null); });
346	    req.on('timeout', () => { req.destroy(); log('andy call timed out'); resolve(null); });
347	    req.write(body); req.end();
348	  });
349	  if (!raw) return { decision: null, raw: null };
350	  const parsed = parseAndyResponse(raw);
351	  if (!parsed) { log(`${ctx.state.name}: no !command() found in Andy's reply: ${raw.slice(0, 200)}`); return { decision: null, raw }; }
352	  const mapped = mapAndyCommand(parsed.cmd, parsed.argStrs);
353	  if (!mapped) { log(`${ctx.state.name}: Andy's '!${parsed.cmd}(...)' didn't map to a known skill -- discarding, not dispatching garbage`); return { decision: null, raw }; }
354	  return { decision: mapped, raw };
355	}
356	
357	function appendDecision(rec) {
358	  try { fs.mkdirSync(LOGS_DIR, { recursive: true }); } catch (e) {}
359	  try { fs.appendFileSync(DECISIONS_FILE, JSON.stringify(rec) + '\n'); } catch (e) { log('decisions.jsonl append failed: ' + e.message); }
360	}
361	
362	// ---- per-bot handling ----
363	async function handleBot(b, rules) {
364	  let st;
365	  try { st = await httpGetJson(b.port, 'state'); } catch (e) { return; }   // unreachable -- skip silently, next poll retries
366	  const dir = st.agenda && st.agenda.direction;
367	  if (!dir || dir.state !== 'needs_direction' || !dir.eid) return;
368	  const eid = dir.eid;
369	
370	  // step 2: conditional driver grace -- an OWNED bot's driver wins the race by default
371	  if (b.owner && (dir.forMs || 0) < DRIVER_GRACE_MS) return;
372	
373	  // step 3: dedup (bot,eid) -- one decision per episode, mechanically, across restarts
374	  state.handled = state.handled || {};
375	  const dedupKey = b.name + ':' + eid;
376	  if (state.handled[dedupKey]) return;
377	
378	  // #97 item 3: a bot that hasn't moved AND is stalling on the exact same why+lastError as
379	  // its LAST dispatch attempt is very unlikely to be helped by dispatching the identical
380	  // thing again -- test-driver's live evidence: three identical chopTrees dispatches from a
381	  // frozen position, back to back, across three separate episodes. Track the signature at
382	  // every genuinely-new-episode attempt (this runs once per eid, gated by the dedup check
383	  // above) and skip the WHOLE decision -- saving an Andy call too, not just the dispatch --
384	  // when nothing observable about the situation has changed since last time. Closes the
385	  // episode via the SAME dirClose #95 already built (closedBy:'frozen_repeat') rather than
386	  // either blindly re-dispatching an identical failing call or leaving the episode open --
387	  // the exact same reopen-backoff every other close uses gives it another shot later if the
388	  // world (position, kit, whatever) actually changes.
389	  // TWO BUGS FOUND LIVE during the deferred wiring check this fixture-zero comment promised
390	  // (2026-09-02, both on the actual restart -- exactly why that check was deferred rather
391	  // than assumed):
392	  // 1. Without an eid in the tracked signature, this fired on the SECOND POLL OF THE SAME
393	  //    STILL-RETRYING EPISODE, not just across genuinely separate episodes -- every poll
394	  //    that passes dedup (including a mid-retry re-poll of an episode decider hasn't given
395	  //    up on yet) unconditionally rewrote `lastAttempt` to the identical {pos,why,lastError},
396	  //    so the very next poll compared it against itself and always matched, short-circuiting
397	  //    the 2-attempt-then-give-up Andy retry after just ONE attempt. Fixed by tracking `eid`
